namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();
    private readonly List<Notification> _notifications = new();

    public NotificationService()
    {
        // Seed initial notifications.
        Add("Welcome to the notification center!");
        Add("Your profile was updated successfully.");
        Add("New comment on your post.");
    }

    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>
    /// Returns notifications with an Id greater than <paramref name="sinceId"/>.
    /// </summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > sinceId).ToList();
        }
    }

    private void Add(string message)
    {
        _notifications.Add(new Notification(_nextId++, message, DateTime.UtcNow));
    }

    /// <summary>
    /// Simulates an external system producing new notifications at random.
    /// Called by a hosted service so the polling page has something to find.
    /// </summary>
    public void GenerateRandom()
    {
        string[] samples =
        [
            "Server CPU usage exceeded 80%.",
            "Deployment to staging completed.",
            "New user signed up.",
            "Payment received.",
            "Disk space running low on db-server-01.",
            "Scheduled maintenance in 30 minutes.",
            "Build #4821 passed all tests.",
        ];

        lock (_lock)
        {
            var msg = samples[Random.Shared.Next(samples.Length)];
            Add(msg);
        }
    }
}

namespace NotificationsApp.Services;

/// <summary>
/// Background hosted service that periodically generates fake notifications
/// so the polling page has new data to discover.
/// </summary>
public class NotificationGeneratorService(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            notifications.GenerateRandom();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications.OrderByDescending(x => x.Id))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // Runs during both static SSR *and* interactive render.
    // PersistentComponentState is unnecessary here because OnInitialized
    // is called only once per render-mode lifetime — the interactive
    // circuit reuses the component instance that was already SSR'd,
    // so the field values survive the transition automatically when
    // using per-page interactive server rendering.
    protected override void OnInitialized()
    {
        _notifications = NotificationSvc.GetAll();
    }

    // Called only once the circuit is live (never during static SSR).
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            var lastId = _notifications.Count > 0
                ? _notifications.Max(n => n.Id)
                : 0;

            var newer = NotificationSvc.GetSince(lastId);

            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);

                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

