+namespace NotificationsApp.Services;
+
+public record Notification(int Id, string Message, DateTime Timestamp);
+
+public class NotificationService
+{
+    private int _nextId = 1;
+    private readonly Lock _lock = new();
+    private readonly List<Notification> _notifications = new();
+
+    public NotificationService()
+    {
+        // Seed initial notifications.
+        Add("Welcome to the notification center!");
+        Add("Your profile was updated successfully.");
+        Add("New comment on your post.");
+    }
+
+    public List<Notification> GetAll()
+    {
+        lock (_lock)
+        {
+            return _notifications.ToList();
+        }
+    }
+
+    /// <summary>
+    /// Returns notifications with an Id greater than <paramref name="sinceId"/>.
+    /// </summary>
+    public List<Notification> GetSince(int sinceId)
+    {
+        lock (_lock)
+        {
+            return _notifications.Where(n => n.Id > sinceId).ToList();
+        }
+    }
+
+    private void Add(string message)
+    {
+        _notifications.Add(new Notification(_nextId++, message, DateTime.UtcNow));
+    }
+
+    /// <summary>
+    /// Simulates an external system producing new notifications at random.
+    /// Called by a hosted service so the polling page has something to find.
+    /// </summary>
+    public void GenerateRandom()
+    {
+        string[] samples =
+        [
+            "Server CPU usage exceeded 80%.",
+            "Deployment to staging completed.",
+            "New user signed up.",
+            "Payment received.",
+            "Disk space running low on db-server-01.",
+            "Scheduled maintenance in 30 minutes.",
+            "Build #4821 passed all tests.",
+        ];
+
+        lock (_lock)
+        {
+            var msg = samples[Random.Shared.Next(samples.Length)];
+            Add(msg);
+        }
+    }
+}
