@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications.OrderByDescending(x => x.Id))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // Runs during both static SSR *and* interactive render.
    // PersistentComponentState is unnecessary here because OnInitialized
    // is called only once per render-mode lifetime — the interactive
    // circuit reuses the component instance that was already SSR'd,
    // so the field values survive the transition automatically when
    // using per-page interactive server rendering.
    protected override void OnInitialized()
    {
        _notifications = NotificationSvc.GetAll();
    }

    // Called only once the circuit is live (never during static SSR).
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            var lastId = _notifications.Count > 0
                ? _notifications.Max(n => n.Id)
                : 0;

            var newer = NotificationSvc.GetSince(lastId);

            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);

                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

